        {
          "source": "ley40",
          "articleId": "a33",
          "paragraph": "1. Cuando de la gestión dimanante de fórmulas conjuntas de actuación entre varias Administraciones públicas se derive responsabilidad en los términos previstos en la presente Ley, las Administraciones intervinientes responderán frente al particular, en todo caso, de forma solidaria. El instrumento jurídico regulador de la actuación conjunta podrá determinar la distribución de la responsabilidad entre las diferentes Administraciones públicas."
        },
        {
          "source": "ley39",
          "articleId": "a81",
          "paragraph": "3. En el caso de reclamaciones en materia de responsabilidad patrimonial del Estado por el funcionamiento anormal de la Administración de Justicia, será preceptivo el informe del Consejo General del Poder Judicial que será evacuado en el plazo máximo de dos meses. El plazo para dictar resolución quedará suspendido por el tiempo que medie entre la solicitud del informe y su recepción, no pudiendo exceder dicho plazo de los citados dos meses."
        }
